// Opens the Things Got Dicey settings window.
// Part of Outrider's Outpost - 0utrider.github.io/outpost
const id = ["dicey", "dicey-dev"].find((m) => game.modules.get(m)?.active);
const menu = id && game.settings.menus.get(`${id}.settingsWindow`);
if (menu) new menu.type().render({ force: true });
else ui.notifications.warn("Things Got Dicey is not active in this world.");
